--
-- Table structure for table `bifrost_menu`
--

DROP TABLE IF EXISTS `bifrost_menu`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bifrost_menu` (
  `gmt_create` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `code` varchar(128) NOT NULL COMMENT '菜单标志 唯一 预留license',
  `level` int(11) NOT NULL DEFAULT '1' COMMENT '级别',
  `sort_no` int(11) DEFAULT '0' COMMENT '排序',
  `type` varchar(2) DEFAULT '0' COMMENT '类型，枚举：0:未知、1:project、2:group、3:menu',
  `path` varchar(255) DEFAULT NULL COMMENT '请求路径',
  `parent_id` bigint(20) DEFAULT NULL COMMENT '上级菜单标志',
  `icon` varchar(255) DEFAULT NULL COMMENT '图标码',
  `name` varchar(40) DEFAULT NULL COMMENT '名称',
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `en_name` varchar(64) DEFAULT NULL COMMENT '英文名称',
  `target` varchar(16) DEFAULT '_self' COMMENT '菜单链接打开方式：_blank、_self、_parent、_top	',
  `create_by` varchar(30) DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(30) DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8 COMMENT='菜单';
/*!40101 SET character_set_client = @saved_cs_client */;

