  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  PRIMARY KEY (`id`),
  KEY `idx_custom_tree_uuid` (`custom_tree_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7727 DEFAULT CHARSET=utf8 COMMENT='菜单功能关系表';
