--
-- Table structure for table `bifrost_role`
--

DROP TABLE IF EXISTS `bifrost_role`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bifrost_role` (
  `gmt_create` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `code` varchar(128) NOT NULL COMMENT '角色标志 唯一',
  `name` varchar(40) NOT NULL COMMENT '角色名称',
  `type` varchar(10) NOT NULL DEFAULT 'default' COMMENT '角色类型 同机构下层次',
  `org_id` bigint(20) NOT NULL COMMENT '所属机构',
  `create_by` varchar(30) DEFAULT NULL COMMENT '创建用户账号',
  `update_by` varchar(30) DEFAULT NULL COMMENT '修改用户账号',
  `en_name` varchar(80) DEFAULT NULL COMMENT '英文机构名称',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8 COMMENT='角色表';
/*!40101 SET character_set_client = @saved_cs_client */;

