--
-- Table structure for table `bifrost_role_menu_function`
--

DROP TABLE IF EXISTS `bifrost_role_menu_function`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bifrost_role_menu_function` (
  `gmt_create` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Ora主键',
  `role_id` bigint(20) NOT NULL COMMENT '角色',
  `menu_id` bigint(20) DEFAULT NULL COMMENT '可用菜单id',
  `function_id` bigint(20) DEFAULT NULL COMMENT '可用功能id',
  `create_by` varchar(30) DEFAULT NULL COMMENT '创建用户账号',
  `update_by` varchar(30) DEFAULT NULL COMMENT '修改用户账号',
  `custom_tree_id` bigint(20) NOT NULL COMMENT 'custom tree id',
  PRIMARY KEY (`id`),
  KEY `idx_role_uuid` (`role_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=20023 DEFAULT CHARSET=utf8 COMMENT='角色和菜单、功能关系表';
/*!40101 SET character_set_client = @saved_cs_client */;

