  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `gmt_create` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `config_key` varchar(64) DEFAULT NULL COMMENT '配置项',
  `config_value` text COMMENT '配置值',
  `created_by` varchar(32) NOT NULL COMMENT '创建人',
  `updated_by` varchar(32) NOT NULL COMMENT '修改人',
  `description` varchar(512) DEFAULT NULL COMMENT '描述信息',
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '状态，0：无效；1：生效',
  `type` varchar(16) NOT NULL DEFAULT 'String' COMMENT 'String、Boolean、Json',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8 COMMENT='系统参数配置';
/*!40101 SET character_set_client = @saved_cs_client */;

