INSERT INTO `bifrost_system_config` VALUES (1,'2019-03-02 16:00:00','2022-06-27 09:42:00','passwordUpdateTime','90','admin','admin','重置密码天数(支持大于1的正整数)。不要删！勿动！',1,'String'),(2,'2019-03-29 08:33:17','2022-06-27 09:42:00','passwordErrorCount','3','admin','admin','登录验证用户名和密码错误次数，大于配置值，则弹出验证码',1,'String'),(3,'2019-03-29 08:33:17','2022-06-27 09:42:00','passwordErrorCountLimit','20','admin','admin','每天密码错误次数(支持大于1的正整数)，超过后当天不能登陆，管理员重置密码后可以登录。不填或者填0系统默认为10次。',1,'String');
/*!40000 ALTER TABLE `bifrost_system_config` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `bifrost_user`
--

DROP TABLE IF EXISTS `bifrost_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bifrost_user` (
  `gmt_create` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `account` varchar(64) NOT NULL DEFAULT '' COMMENT '账号',
  `user_name` varchar(64) DEFAULT NULL COMMENT '用户名称',
  `pwd` varchar(32) NOT NULL COMMENT '密码',
  `jobs` varchar(100) DEFAULT NULL COMMENT '岗位',
  `avatar` mediumtext COMMENT '头像',
  `expiration` datetime DEFAULT NULL COMMENT '过期时间',
  `gender` int(11) DEFAULT NULL COMMENT '性别 0:未知;1:男;2:女',
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '用户状态 0:正常',
  `create_by` varchar(30) DEFAULT NULL COMMENT '创建用户账号',
  `update_by` varchar(30) DEFAULT NULL COMMENT '修改用户账号',
  `lang` varchar(16) DEFAULT NULL COMMENT '语言',
  `theme` varchar(32) DEFAULT NULL COMMENT '主题',
  `layout` varchar(32) DEFAULT NULL COMMENT '布局',
  `simplified` int(11) DEFAULT NULL COMMENT '是否简体：1是0否',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号码',
  `sign` varchar(1024) DEFAULT NULL COMMENT '个性签名',
  `salt` varchar(32) NOT NULL DEFAULT '' COMMENT '盐值',
  `tokenMD5` varchar(32) DEFAULT NULL COMMENT '用户登录tokenMD5',
  `en_user_name` varchar(40) DEFAULT NULL COMMENT '英文用户名称',
  `try_time` int(11) DEFAULT '0' COMMENT '密码错误次数',
  `try_date` timestamp NULL DEFAULT NULL COMMENT '密码重试时间',
  `update_pwd_time` timestamp NULL DEFAULT NULL COMMENT '密码修改时间',
  `first_login` varchar(10) DEFAULT '0' COMMENT '第一次登陆标志位，1、已登录，0或者null，初次登录',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱',
  `parent_id` bigint(20) DEFAULT NULL,
  `main_code` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_account` (`account`)
) ENGINE=InnoDB AUTO_INCREMENT=120 DEFAULT CHARSET=utf8 COMMENT='用户表';
/*!40101 SET character_set_client = @saved_cs_client */;

